"""Plain-language A–O results from saved artifacts only."""
import datetime,json,pathlib,sys
ROOT=pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'algo-trading-bot'))
from exchange.paper_operations import atomic_json

def write_report(out):
 out=pathlib.Path(out);seq=json.loads((out/'sequence.json').read_text());tests=json.loads((out/'test_receipt.json').read_text())
 results={}
 for label,folder in [('short_30m','short_soak'),('long_3h','long_soak')]:
  p=out/folder/(label+'_certification.json')
  if p.exists():results[label]=json.loads(p.read_text())
 final=results.get('long_3h',results.get('short_30m'));done='finished_unix' in seq
 verdict=final['verdict'] if done and final else 'IMPLEMENTATION_COMPLETE_TEST_PENDING'
 if seq['phase'] in {'FAILED','SOURCE_CHANGED'}:verdict='IMPLEMENTATION_FAILED'
 stage={s['stage']:s for s in final['funnel']['session']['stages']} if final else {}
 flags=dict(STRATEGY_FREEZE='PASS' if tests['checks_before']['strategy_freeze']['exit_code']==0 else 'FAIL',TESTS_PASS=tests['passed'],TRANSPORT_READY=bool(final and final['checks']['final_transport_recovered']),SUBSCRIPTIONS_READY=bool(final and final['checks']['subscriptions_confirmed_once']),REST_RECOVERY_READY=bool(final and final['checks']['no_pending_rest'] and final['checks']['no_accounting_halt']),MARKET_HEALTH_READY=bool(final and final['checks']['repeated_usable_feed_observations']),QUARANTINE_READY='IMPLEMENTED_OFFLINE_TESTED' if not final else 'OBSERVED' if final['quarantine_observed'] else 'NOT_EXERCISED_IN_THIS_RUN',HEALTH_REPORT_READY=True,FEED_READY=bool(done and final and final['feed_certified']),CONTROLLED_EXECUTION_READY=False,PRACTICE_READY=False,LIVE_READY=False)
 summary=dict(generated_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),verdict=verdict,sequence=seq,full_regression=tests,results=results,flags=flags,execution_mode='PAPER',allow_live_orders=False,protection_enabled=False,actual_orders=final['actual_exchange_orders'] if final else None,baseline_scope='Cumulative 370/49/7/0 includes earlier five-minute segment; actual old three-hour comparison 360/48/7/0. Previous instrumented run 360/34/6/0.',funded_account_certified=False)
 atomic_json(out/('final_summary.json' if done else 'progress.json'),summary)
 lines=['# Team Anchorium — market resilience report','', '## SECTION A — EXECUTIVE VERDICT','',f'**{verdict}.** '+('The bounded test sequence has finished.' if done else 'Implementation and offline verification are complete; public PAPER certification is still running.'),'No actual order or funded activation is authorized. The PAPER ledger is separate from the team wallet.','', '## SECTION B — ROOT CAUSE','', 'Per-symbol circuit breakers already existed, so a stale market did not inherently block every healthy market. The recurring global warning often meant zero usable markets in the streaming cache. The independent REST scanner could observe newer inputs while that cache stayed old. Successful but stale/incomplete REST responses were not scheduled for automatic repair, and a narrow tail request could not fill an older missing bar. Malformed data for a known symbol could also unnecessarily disconnect the common socket. The old health command hid these distinctions behind one generic message. Genuine zero-usable-market periods still remain degraded.','', '## SECTION C — FILES CHANGED','', '| Path | Class/function | Purpose |','|---|---|---|',
 '| algo-trading-bot/exchange/market_health.py | MarketHealthManager / validate_history | One shared quarantine, integrity, retry and restoration state per symbol |',
 '| algo-trading-bot/exchange/hyperliquid_market_data.py | ingest / reconcile_history / market_health / publish_public_snapshot | Symbol-local invalid inputs; bounded real-bar recovery; one worker; share validated REST facts |',
 '| algo-trading-bot/market_regime_scanner.py | scan | Validate inputs before frozen brain; retain full original UTC lookback and ranking |',
 '| algo-trading-bot/market_stream.py | health / poll | Use shared market gates and preserve account reconciliation barrier |',
 '| algo-trading-bot/exchange/paper_operations.py | PaperHealth.write | Partial health plus explicit transport, subscriptions, account, budget and global gates |',
 '| scripts/check_practice_health.py | assess / describe | Human-readable details; 0 healthy/partial, 2 degraded, 1 stale/invalid, 3 stopped |',
 '| algo-trading-bot/exchange/rate_limits.py | report | Public read throttle separate from unobserved account-action budget |',
 '| algo-trading-bot/opportunity_funnel.py | reason_code / observe_scan | Normalize new infrastructure gates; independent and sequential denominators |',
 '| scripts/run_crypto_paper.py | main/finally | Share manager; refresh drained end-state health without changing strategy |',
 '| exchange/market_resilience_certification.py; scripts/market_resilience_report.py | evidence evaluation | New requested usable-feed definition; preserve older three-scan certificate separately |',
 '| scripts/run_feed_soak.py | main | Source-bound resilience report option; original default remains |',
 '| algo-trading-bot/test_market_resilience.py; test_crypto_paper_infrastructure.py | tests/fixtures | New safety/resilience cases and updated fake runtime interface |',
 '', '## SECTION D — PER-MARKET HEALTH','', 'Each par market has independent candle, book, context, history and tick clocks, reason codes, quarantine state and retry time. All 300 completed bars, real timestamps, chronology, uniqueness, OHLCV, fresh book/context and numeric spread validity must pass. Fresh prices cannot validate stale history. Wide but structurally valid spread is feed data; the original 15 bps strategy admission limit still rejects that market later. Full UTC-anchored scanner input stays unchanged, including warmup. A hole outside the engine\'s 300-bar buffer remains blocked until the scanner revalidates its full input.','', '## SECTION E — REST RECOVERY','', 'One worker requests only actual par exchange candles, validates them, deduplicates identical rows, rejects conflicting/future/malformed facts, orders by timestamp and merges without replacing newer WebSocket facts. A short or gapped buffer requires the bounded full 300-bar window; a valid buffer uses a small overlapping tail. Missing bars stay missing. No historical research CSV or generated bar is a fallback.','', '## SECTION F — QUARANTINE','', 'An invalid symbol is blocked from the brain and entry path. Other validated symbols continue. Pending repair blocks only its selected symbols. Unsuccessful repairs back off from 30 seconds to at most five minutes; successful real data restores eligibility without restarting the bot. Restored eligibility still passes the unchanged scanner, strategy, economics and risk checks.','', '## SECTION G — HEALTH CHECK OUTPUT','', 'The health command now shows overall state, transport, confirmed/desired subscriptions, duplicates, reconciliation, usable/total markets, each symbol\'s reasons and completed-bar count, feed readiness, trade readiness and genuine global blockers. PARTIAL_HEALTHY can exit 0 only when all global gates pass and at least one market is valid. All-market failure, accounting failure, unknown account state, unrecovered transport, missing subscriptions or real budget throttling still exit degraded.']
 if final:
  lines+=['', 'Actual saved operating example: see the current stage certification Markdown. It is explicitly timestamped historical evidence, not a current running-process claim.']
 lines+=['', '## SECTION H — WEBSOCKET EXPIRY','', 'Received 1000 / Expired closes pause new entries, then one owner reconnects, restores the fixed subscriptions, reconciles public/account state and revalidates each market. Recovered past errors remain evidence; they are cleared from current global status. Unknown/wrong venue identities still fail closed. Old generic close causes remain unknown.','', '## SECTION I — RATE-LIMIT SAFETY','', 'The existing single-flight and weighted rate manager remains authoritative. There is one repair worker, no unbounded history download, per-symbol retry deadlines and preserved safety reserves. Public-read throttling is a real global blocker; account-action UNKNOWN in a public-only manager is not proof of exhausted public reads. No new SDK/signing path exists.','', '## SECTION J — STRATEGY INTEGRITY','', 'Strategy freeze: '+json.dumps(tests['checks_before']['strategy_freeze']['result'])+'. signal_brain.py and frozen methods/parameters remain unchanged. ATR 0.40%, spread 15 bps, 300 completed bars, Top-3, UTC VWAP and all management concepts remain unchanged. Every run binds before/after source hashes and checkpoint identities.','', '## SECTION K — TEST RESULTS','',f'Previous total: 1301. New total: {tests["totals"]["tests"]}. Added: {tests["totals"]["tests"]-1301}. Failures: {tests["totals"]["failures"]}; errors: {tests["totals"]["errors"]}; skipped: {tests["totals"]["skipped"]}. Full source-bound regression passed: {tests["passed"]}. Phase-0 and production order lockouts are included. Fixtures prove behavior offline and do not certify the funded wallet.','', '## SECTION L — 30-MINUTE PAPER RESULTS','']
 if 'short_30m' in results:
  x=results['short_30m'];lines += [f'Runtime {x["duration_seconds"]:.3f}s; captured socket uptime {x["transport_uptime_seconds"]:.3f}s; disconnects {x["disconnect_count"]}; successful reconnect barriers {x["successful_reconnect_account_barriers"]}; duplicate subscriptions {x["duplicate_subscriptions"]}.',f'Final usable markets: {x["final_usable_markets"]}. Quarantined during run: {x["quarantine_observed"]}. Restored after quarantine: {x["restored_after_quarantine"]}. Partial-health samples: {x["partial_healthy_samples"]}. Feed certified: {x["feed_certified"]}; blockers: {x["blockers"]}.',f'Actual orders: {x["actual_exchange_orders"]}; PAPER fills: {x["local_fills"]}; PAPER accounting: {json.dumps(x["paper_results"])}.',f'Both checkpoint checks: {json.dumps(x["checkpoints"])}. Health tape digest match: {x["health_samples_checksum_matches"]}.',f'Maximum receiver gap: {x["maximum_receiver_gap_seconds"]:.3f}s; maximum sampled local IP weight: {x["maximum_sampled_local_ip_weight"]}. This is not exchange-wide IP measurement.','Actual close records: '+json.dumps(x['close_records'])+'.']
 else:lines+=['PENDING. No 30-minute result is claimed before the receipt exists.']
 if 'long_3h' in results:
  x=results['long_3h'];lines+=['',f'Gated three-hour follow-up: {x["duration_seconds"]:.3f}s, {x["this_run_observations"]} observations, {x["verdict"]}. {x["disconnect_count"]} closes; {x["successful_reconnect_account_barriers"]} successful reconnect barriers; {x["rest_reconciliations_including_initial"]} REST reconciliations includes startup. Receiver gap {x["maximum_receiver_gap_seconds"]:.3f}s; socket uptime {x["transport_uptime_seconds"]:.3f}s. Blockers: {x["blockers"]}.']
 lines+=['', '## SECTION M — BEFORE VS AFTER','', 'Requested cumulative old baseline: 370 observations / 49 healthy / 7 spread / 0 ATR / 0 qualified. Its actual three-hour segment: 360 / 48 / 7 / 0 / 0. Previous instrumented source: 360 / 34 / 6 / 0 / 0. These denominators are separate. Public conditions occur at different times; changes in market availability cannot be attributed to code alone.']
 if final:
  lines+=['','| Stage | Evaluated | Passed | Failed | Pass % | Sequential admitted/evaluated |','|---|---:|---:|---:|---:|---:|']
  for z in final['funnel']['session']['stages']:
   pct=f'{z["pass_percent"]:.2f}%' if z['pass_percent'] is not None else 'Not evaluated'
   lines.append(f'| {z["stage"]} | {z["evaluated"]} | {z["passed"]} | {z["failed"]} | {pct} | {z["admission_passed"]}/{z["admission_evaluated"]} |')
  lines+=['','First rejection categories (one first rejection per market-cycle): '+json.dumps(final['funnel']['session']['first_rejection_categories'])+'. All observed failures can overlap and are retained in the certificate. Strategy/risk stages not reached are not counted as passed.','', '| Market | Scanner windows | Healthy | Failed | Healthy % | Final state |','|---|---:|---:|---:|---:|---|']
  for sym,v in final['per_market'].items():lines.append(f'| {sym} | {v["evaluated"]} | {v["healthy"]} | {v["failed"]} | {v["healthy_percent"]:.2f}% | {final["last_market_health"].get(sym,{}).get("state","UNKNOWN")} |')
  lines+=['','Transport/source and quarantine details are in the stage JSON. Old baseline reconnect successes, duplicate subscriptions and unrecorded close codes remain unknown. Baseline 23 disconnect events included 2 heartbeat and 6 REST retry failures. Instrumented previous run had 16 captured Expired closes, zero heartbeat/REST failures. A trade increase is not the success criterion.']
 else:lines+=['New public-run counts remain pending; no guessed after column is provided.']
 lines+=['', '## SECTION N — FINAL FLAGS','', '```ini']+[f'{k} = {str(v).upper()}' for k,v in flags.items()]+['EXECUTION_MODE = PAPER','ALLOW_LIVE_ORDERS = false','PROTECTION_ENABLED = false','```','', 'Funded LONG/SHORT, exchange protection acceptance, funded recovery and accounting certification are not performed. The 7 October read-only account/signer checks are timestamped local observations, not fresh execution readiness. Future funded testing requires a fresh preflight and separate explicit user activation.','', '## SECTION O — EXACT NEXT ACTION','']
 if not done:lines+=['Finish the already launched bounded PAPER sequence and inspect its source-bound receipts; do not start a duplicate.']
 elif verdict=='FEED_READY':lines+=['Prepare the concrete, minimal funded-certification risk budget for human review; keep all order/protection locks closed.']
 elif verdict=='IMPLEMENTATION_FAILED':lines+=['Investigate the saved failed-stage reason before any fresh test; preserve its evidence.']
 else:lines+=['Review the specific failed market-data gates with the organizer using the saved real timestamps and gaps; retain PAPER and unchanged strategy thresholds.']
 (out/'report.md').write_text('\n'.join(lines)+'\n')
 return summary

if __name__=='__main__':write_report(pathlib.Path(__file__).resolve().parent)
